const geminiRes = $input.first().json;
const ctx = $('Gemini-Anfrage bauen').first().json.context;
const today = (ctx && ctx.date) ? ctx.date : new Date().toISOString().split('T')[0];

let text = '';
try {
  text = geminiRes.candidates[0].content.parts[0].text || '{}';
} catch(e) {
  text = '{}';
}

let parsed;
try {
  // Strip markdown code blocks if present
  text = text.replace(/```json\s*/gi, '').replace(/```\s*/g, '').trim();
  const match = text.match(/\{[\s\S]*\}/);
  parsed = JSON.parse(match ? match[0] : text);
  if (!parsed.missions || !Array.isArray(parsed.missions) || parsed.missions.length === 0) {
    throw new Error('Empty missions array');
  }
} catch(e) {
  // Regel-basierter Fallback
  const gap = (ctx && ctx.revenueGap) ? ctx.revenueGap : ((ctx && ctx.monthGoal) ? ctx.monthGoal : 2870);
  const pct = (ctx && ctx.monthPct) ? ctx.monthPct : 0;
  const daysLeft = (ctx && ctx.daysLeft) ? ctx.daysLeft : 15;
  const streak = (ctx && ctx.streak) ? ctx.streak : 0;
  const missions = [];
  let rank = 1;
  if (gap > 500) {
    missions.push({ rank: rank++, task: '3 Mittelständler via Google Maps ansprechen', pillar: 'Coaching', why: '\u20ac' + gap + ' fehlen noch – direkter Outreach bringt am schnellsten neue Kunden', tools: ['outreach_sniper.py'] });
    missions.push({ rank: rank++, task: 'LinkedIn-Post: Expertise zu Prozess-Coaching teilen', pillar: 'Branding', why: 'Regelmäßige Sichtbarkeit baut Inbound-Pipeline auf', tools: ['Sociamonials'] });
  }
  if (streak < 3) {
    missions.push({ rank: rank++, task: '20 Min Pause + kurzer Spaziergang', pillar: 'Bio-Struktur', why: 'Streak unter 3 – Regeneration verhindert Burnout und erhöht Fokus', tools: [] });
  }
  missions.push({ rank: rank++, task: 'n8n Jarvis-Workflow testen und validieren', pillar: 'Bot-Empire', why: 'Automatisiertes Tages-Briefing spart täglich 15 Min und skaliert Einnahmen', tools: ['n8n'] });
  if (missions.length < 3) {
    missions.push({ rank: rank++, task: 'Amazon Affiliate: 1 Produkt identifizieren und Link erstellen', pillar: 'Affiliate', why: 'Passives Einkommen aufbauen parallel zu aktivem Coaching', tools: ['NeuronWriter'] });
  }
  parsed = {
    missions: missions.slice(0, 5),
    daily_focus: gap > 1000 ? 'Umsatz-Lücke schließen – Coaching-Outreach ist Priorität 1' : 'Wachstum über Automatisierung + Content skalieren',
    alert: (daysLeft < 10 && pct < 50) ? '\u26a0\ufe0f Alarm: Nur noch ' + daysLeft + ' Tage – erst ' + pct + '% des Monatsziels erreicht!' : null,
    _source: 'offline-fallback'
  };
}

const savePayload = JSON.stringify([{
  date: today,
  missions: parsed.missions,
  daily_focus: parsed.daily_focus,
  context: ctx || {},
  created_at: new Date().toISOString()
}]);

return [{
  json: {
    missions: parsed.missions,
    daily_focus: parsed.daily_focus,
    alert: parsed.alert || null,
    _source: parsed._source || 'gemini',
    _savePayload: savePayload
  }
}];

const rows = $input.first().json;
const record = Array.isArray(rows) && rows.length > 0 ? rows[0] : null;

if (!record || !record.missions) {
  return [{ json: { text: '🧠 Jarvis: Keine Missions für heute gefunden. Seite öffnen um neue zu generieren!' } }];
}

const topMissions = record.missions.slice(0, 3).map((m, i) => (i + 1) + '. ' + m.task).join('\n');
const focus = record.daily_focus || '';
const date = new Date().toLocaleDateString('de-DE', { weekday: 'long', day: '2-digit', month: '2-digit', year: 'numeric' });

const text = '\ud83e\udde0 *Jarvis Morgen-Briefing*\n' + date + '\n\n\ud83d\udccb *Heute\'s Missions:*\n' + topMissions + (focus ? '\n\n\ud83c\udfaf *Fokus:* ' + focus : '') + '\n\n\u2600\ufe0f Guten Morgen, Canberk! Let\'s go.';

return [{ json: { text } }];
